#!/usr/bin/env python3
from pathlib import Path
import base64, io, tarfile, sys
DATA = r"""[...truncated for payload safety...]"""
out = Path(sys.argv[1] if len(sys.argv)>1 else "otamatone64/src")
out.mkdir(parents=True, exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(DATA)), mode="r:gz") as t:
    t.extractall(out)
print("Generated Otamatone64 native source:", len(list(out.iterdir())), "files")
